     6  static int chunk_fits_in_cache(spng_ctx *ctx, size_t *new_usage)
     7  {
     8      if(ctx == NULL || new_usage == NULL) return 0;
     9
    10      size_t usage = ctx->chunk_cache_usage + (size_t)ctx->current_chunk.length;
    11
    12      if(usage < ctx->chunk_cache_usage) return 0; /* overflow */
    13
    14      if(usage > ctx->chunk_cache_limit) return 0;
    15
    16      *new_usage = usage;
    17
    18      return 1;
    19  }
