    21  /*
    22      Read and validate all critical and relevant ancillary chunks up to the first IDAT
    23      Returns zero and sets ctx->first_idat on success
    24  */
    25  static int read_chunks_before_idat(spng_ctx *ctx)
    26  {
    27      if(ctx == NULL) return 1;
    28      if(ctx->data == NULL) return 1;
    29      if(!ctx->valid_state) return SPNG_EBADSTATE;
    30
    31      int ret, discard;
    32      unsigned char *data;
    33      struct spng_chunk chunk;
    34
    35      chunk.offset = 8;
    36      chunk.length = 13;
    37      size_t sizeof_sig_ihdr = 29;
    38
    39      ret = read_data(ctx, sizeof_sig_ihdr);
    40      if(ret) return ret;
    41
    42      data = ctx->data;
    43
    44      uint8_t signature[8] = { 137, 80, 78, 71, 13, 10, 26, 10 };
    45      if(memcmp(data, signature, sizeof(signature))) return SPNG_ESIGNATURE;
    46
    47      chunk.length = read_u32(data + 8);
    48      memcpy(&chunk.type, data + 12, 4);
    49
    50      if(chunk.length != 13) return SPNG_EIHDR_SIZE;
    51      if(memcmp(chunk.type, type_ihdr, 4)) return SPNG_ENOIHDR;
    52
    53      ctx->cur_actual_crc = crc32(0, NULL, 0);
    54      ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, data + 12, 17);
    55
    56      ctx->ihdr.width = read_u32(data + 16);
    57      ctx->ihdr.height = read_u32(data + 20);
    58      memcpy(&ctx->ihdr.bit_depth, data + 24, 1);
    59      memcpy(&ctx->ihdr.color_type, data + 25, 1);
    60      memcpy(&ctx->ihdr.compression_method, data + 26, 1);
    61      memcpy(&ctx->ihdr.filter_method, data + 27, 1);
    62      memcpy(&ctx->ihdr.interlace_method, data + 28, 1);
    63
    64      if(!ctx->max_width) ctx->max_width = png_u32max;
    65      if(!ctx->max_height) ctx->max_height = png_u32max;
    66
    67      ret = check_ihdr(&ctx->ihdr, ctx->max_width, ctx->max_height);
    68      if(ret) return ret;
    69
    70      ctx->file_ihdr = 1;
    71      ctx->stored |= SPNG_CHUNK_IHDR;
    72
    73      while( !(ret = read_header(ctx, &discard)))
    74      {
    75          memcpy(&chunk, &ctx->current_chunk, sizeof(struct spng_chunk));
    76
    77          if(!memcmp(chunk.type, type_idat, 4))
    78          {
    79              memcpy(&ctx->first_idat, &chunk, sizeof(struct spng_chunk));
    80              return 0;
    81          }
    82
    83          if(!chunk_fits_in_cache(ctx, &ctx->chunk_cache_usage))
    84          {
    85              ret = discard_chunk_bytes(ctx, chunk.length);
    86              if(ret) return ret;
    87              continue;
    88          }
    89
    90          data = ctx->data;
    91
    92          ret = read_chunk_bytes(ctx, chunk.length);
    93          if(ret) return ret;
    94
    95          /* Ignore private chunks */
    96          if( (chunk.type[1] & (1 << 5)) != 0) continue;
    97
    98          if(is_critical_chunk(&chunk)) /* Critical chunk */
    99          {
   100              if(!memcmp(chunk.type, type_plte, 4))
   101              {
   102                  if(chunk.length == 0) return SPNG_ECHUNK_SIZE;
   103                  if(chunk.length % 3 != 0) return SPNG_ECHUNK_SIZE;
   104                  if( (chunk.length / 3) > 256 ) return SPNG_ECHUNK_SIZE;
   105
   106                  if(ctx->ihdr.color_type == 3)
   107                  {
   108                      if(chunk.length / 3 > (1 << ctx->ihdr.bit_depth) ) return SPNG_ECHUNK_SIZE;
   109                  }
   110
   111                  ctx->plte.n_entries = chunk.length / 3;
   112
   113                  size_t i;
   114                  for(i=0; i < ctx->plte.n_entries; i++)
   115                  {
   116                      memcpy(&ctx->plte.entries[i].red,   data + i * 3, 1);
   117                      memcpy(&ctx->plte.entries[i].green, data + i * 3 + 1, 1);
   118                      memcpy(&ctx->plte.entries[i].blue,  data + i * 3 + 2, 1);
   119                  }
   120
   121                  ctx->plte_offset = chunk.offset;
   122
   123                  ctx->file_plte = 1;
   124              }
   125              else if(!memcmp(chunk.type, type_iend, 4)) return SPNG_ECHUNK_POS;
   126              else if(!memcmp(chunk.type, type_ihdr, 4)) return SPNG_ECHUNK_POS;
   127              else return SPNG_ECHUNK_UNKNOWN_CRITICAL;
   128          }
   129          else if(!memcmp(chunk.type, type_chrm, 4)) /* Ancillary chunks */
   130          {
   131              if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
   132              if(ctx->file_chrm) return SPNG_EDUP_CHRM;
   133
   134              if(chunk.length != 32) return SPNG_ECHUNK_SIZE;
   135
   136              ctx->chrm_int.white_point_x = read_u32(data);
   137              ctx->chrm_int.white_point_y = read_u32(data + 4);
   138              ctx->chrm_int.red_x = read_u32(data + 8);
   139              ctx->chrm_int.red_y = read_u32(data + 12);
   140              ctx->chrm_int.green_x = read_u32(data + 16);
   141              ctx->chrm_int.green_y = read_u32(data + 20);
   142              ctx->chrm_int.blue_x = read_u32(data + 24);
   143              ctx->chrm_int.blue_y = read_u32(data + 28);
   144
   145              if(check_chrm_int(&ctx->chrm_int)) return SPNG_ECHRM;
   146
   147              ctx->file_chrm = 1;
   148              ctx->stored |= SPNG_CHUNK_CHRM;
   149          }
   150          else if(!memcmp(chunk.type, type_gama, 4))
   151          {
   152              if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
   153              if(ctx->file_gama) return SPNG_EDUP_GAMA;
   154
   155              if(chunk.length != 4) return SPNG_ECHUNK_SIZE;
   156
   157              ctx->gama = read_u32(data);
   158
   159              if(!ctx->gama) return SPNG_EGAMA;
   160              if(ctx->gama > png_u32max) return SPNG_EGAMA;
   161
   162              ctx->file_gama = 1;
   163              ctx->stored |= SPNG_CHUNK_GAMA;
   164          }
   165          else if(!memcmp(chunk.type, type_iccp, 4))
   166          {
   167              if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
   168              if(ctx->file_iccp) return SPNG_EDUP_ICCP;
   169              if(!chunk.length) return SPNG_ECHUNK_SIZE;
   170
   171              continue; /* XXX: https://gitlab.com/randy408/libspng/issues/31 */
   172          }
   173          else if(!memcmp(chunk.type, type_sbit, 4))
   174          {
   175              if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
   176              if(ctx->file_sbit) return SPNG_EDUP_SBIT;
   177
   178              if(ctx->ihdr.color_type == 0)
   179              {
   180                  if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
   181
   182                  memcpy(&ctx->sbit.grayscale_bits, data, 1);
   183              }
   184              else if(ctx->ihdr.color_type == 2 || ctx->ihdr.color_type == 3)
   185              {
   186                  if(chunk.length != 3) return SPNG_ECHUNK_SIZE;
   187
   188                  memcpy(&ctx->sbit.red_bits, data, 1);
   189                  memcpy(&ctx->sbit.green_bits, data + 1 , 1);
   190                  memcpy(&ctx->sbit.blue_bits, data + 2, 1);
   191              }
   192              else if(ctx->ihdr.color_type == 4)
   193              {
   194                  if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
   195
   196                  memcpy(&ctx->sbit.grayscale_bits, data, 1);
   197                  memcpy(&ctx->sbit.alpha_bits, data + 1, 1);
   198              }
   199              else if(ctx->ihdr.color_type == 6)
   200              {
   201                  if(chunk.length != 4) return SPNG_ECHUNK_SIZE;
   202
   203                  memcpy(&ctx->sbit.red_bits, data, 1);
   204                  memcpy(&ctx->sbit.green_bits, data + 1, 1);
   205                  memcpy(&ctx->sbit.blue_bits, data + 2, 1);
   206                  memcpy(&ctx->sbit.alpha_bits, data + 3, 1);
   207              }
   208
   209              if(check_sbit(&ctx->sbit, &ctx->ihdr)) return SPNG_ESBIT;
   210
   211              ctx->file_sbit = 1;
   212              ctx->stored |= SPNG_CHUNK_SBIT;
   213          }
   214          else if(!memcmp(chunk.type, type_srgb, 4))
   215          {
   216              if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
   217              if(ctx->file_srgb) return SPNG_EDUP_SRGB;
   218
   219              if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
   220
   221              memcpy(&ctx->srgb_rendering_intent, data, 1);
   222
   223              if(ctx->srgb_rendering_intent > 3) return SPNG_ESRGB;
   224
   225              ctx->file_srgb = 1;
   226              ctx->stored |= SPNG_CHUNK_SRGB;
   227          }
   228          else if(!memcmp(chunk.type, type_bkgd, 4))
   229          {
   230              if(ctx->file_plte && chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
   231              if(ctx->file_bkgd) return SPNG_EDUP_BKGD;
   232
   233              uint16_t mask = ~0;
   234              if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
   235
   236              if(ctx->ihdr.color_type == 0 || ctx->ihdr.color_type == 4)
   237              {
   238                  if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
   239
   240                  ctx->bkgd.gray = read_u16(data) & mask;
   241              }
   242              else if(ctx->ihdr.color_type == 2 || ctx->ihdr.color_type == 6)
   243              {
   244                  if(chunk.length != 6) return SPNG_ECHUNK_SIZE;
   245
   246                  ctx->bkgd.red = read_u16(data) & mask;
   247                  ctx->bkgd.green = read_u16(data + 2) & mask;
   248                  ctx->bkgd.blue = read_u16(data + 4) & mask;
   249              }
   250              else if(ctx->ihdr.color_type == 3)
   251              {
   252                  if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
   253                  if(!ctx->file_plte) return SPNG_EBKGD_NO_PLTE;
   254
   255                  memcpy(&ctx->bkgd.plte_index, data, 1);
   256                  if(ctx->bkgd.plte_index >= ctx->plte.n_entries) return SPNG_EBKGD_PLTE_IDX;
   257              }
   258
   259              ctx->file_bkgd = 1;
   260              ctx->stored |= SPNG_CHUNK_BKGD;
   261          }
   262          else if(!memcmp(chunk.type, type_trns, 4))
   263          {
   264              if(ctx->file_plte && chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
   265              if(ctx->file_trns) return SPNG_EDUP_TRNS;
   266              if(!chunk.length) return SPNG_ECHUNK_SIZE;
   267
   268              uint16_t mask = ~0;
   269              if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
   270
   271              if(ctx->ihdr.color_type == 0)
   272              {
   273                  if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
   274
   275                  ctx->trns.gray = read_u16(data) & mask;
   276              }
   277              else if(ctx->ihdr.color_type == 2)
   278              {
   279                  if(chunk.length != 6) return SPNG_ECHUNK_SIZE;
   280
   281                  ctx->trns.red = read_u16(data) & mask;
   282                  ctx->trns.green = read_u16(data + 2) & mask;
   283                  ctx->trns.blue = read_u16(data + 4) & mask;
   284              }
   285              else if(ctx->ihdr.color_type == 3)
   286              {
   287                  if(chunk.length > ctx->plte.n_entries) return SPNG_ECHUNK_SIZE;
   288                  if(!ctx->file_plte) return SPNG_ETRNS_NO_PLTE;
   289
   290                  size_t k;
   291                  for(k=0; k < chunk.length; k++)
   292                  {
   293                      memcpy(&ctx->trns.type3_alpha[k], data + k, 1);
   294                  }
   295                  ctx->trns.n_type3_entries = chunk.length;
   296              }
   297              else return SPNG_ETRNS_COLOR_TYPE;
   298
   299              ctx->file_trns = 1;
   300              ctx->stored |= SPNG_CHUNK_TRNS;
   301          }
   302          else if(!memcmp(chunk.type, type_hist, 4))
   303          {
   304              if(!ctx->file_plte) return SPNG_EHIST_NO_PLTE;
   305              if(chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
   306              if(ctx->file_hist) return SPNG_EDUP_HIST;
   307
   308              if( (chunk.length / 2) != (ctx->plte.n_entries) ) return SPNG_ECHUNK_SIZE;
   309
   310              size_t k;
   311              for(k=0; k < (chunk.length / 2); k++)
   312              {
   313                  ctx->hist.frequency[k] = read_u16(data + k*2);
   314              }
   315
   316              ctx->file_hist = 1;
   317              ctx->stored |= SPNG_CHUNK_HIST;
   318          }
   319          else if(!memcmp(chunk.type, type_phys, 4))
   320          {
   321              if(ctx->file_phys) return SPNG_EDUP_PHYS;
   322
   323              if(chunk.length != 9) return SPNG_ECHUNK_SIZE;
   324
   325              ctx->phys.ppu_x = read_u32(data);
   326              ctx->phys.ppu_y = read_u32(data + 4);
   327              memcpy(&ctx->phys.unit_specifier, data + 8, 1);
   328
   329              if(check_phys(&ctx->phys)) return SPNG_EPHYS;
   330
   331              ctx->file_phys = 1;
   332              ctx->stored |= SPNG_CHUNK_PHYS;
   333          }
   334          else if(!memcmp(chunk.type, type_splt, 4))
   335          {
   336              if(ctx->user_splt) continue; /* XXX: should check profile names for uniqueness */
   337              if(!chunk.length) return SPNG_ECHUNK_SIZE;
   338
   339              ctx->file_splt = 1;
   340
   341              if( !(ctx->stored & SPNG_CHUNK_SPLT) )
   342              {
   343                  ctx->n_splt = 1;
   344                  ctx->splt_list = spng__calloc(ctx, 1, sizeof(struct spng_splt));
   345                  if(ctx->splt_list == NULL) return SPNG_EMEM;
   346              }
   347              else
   348              {
   349                  ctx->n_splt++;
   350                  if(ctx->n_splt < 1) return SPNG_EOVERFLOW;
   351                  if(sizeof(struct spng_splt) > SIZE_MAX / ctx->n_splt) return SPNG_EOVERFLOW;
   352
   353                  void *buf = spng__realloc(ctx, ctx->splt_list, ctx->n_splt * sizeof(struct spng_splt));
   354                  if(buf == NULL) return SPNG_EMEM;
   355                  ctx->splt_list = buf;
   356                  memset(&ctx->splt_list[ctx->n_splt - 1], 0, sizeof(struct spng_splt));
   357              }
   358
   359              uint32_t i = ctx->n_splt - 1;
   360
   361              size_t keyword_len = chunk.length > 80 ? 80 : chunk.length;
   362              char *keyword_nul = memchr(data, '\0', keyword_len);
   363              if(keyword_nul == NULL) return SPNG_ESPLT_NAME;
   364
   365              memcpy(&ctx->splt_list[i].name, data, keyword_len);
   366
   367              if(check_png_keyword(ctx->splt_list[i].name)) return SPNG_ESPLT_NAME;
   368
   369              keyword_len = strlen(ctx->splt_list[i].name);
   370
   371              if( (chunk.length - keyword_len - 1) ==  0) return SPNG_ECHUNK_SIZE;
   372
   373              memcpy(&ctx->splt_list[i].sample_depth, data + keyword_len + 1, 1);
   374
   375              if(ctx->n_splt > 1)
   376              {
   377                  uint32_t j;
   378                  for(j=0; j < i; j++)
   379                  {
   380                      if(!strcmp(ctx->splt_list[j].name, ctx->splt_list[i].name)) return SPNG_ESPLT_DUP_NAME;
   381                  }
   382              }
   383
   384              if(ctx->splt_list[i].sample_depth == 16)
   385              {
   386                  if( (chunk.length - keyword_len - 2) % 10 != 0) return SPNG_ECHUNK_SIZE;
   387                  ctx->splt_list[i].n_entries = (chunk.length - keyword_len - 2) / 10;
   388              }
   389              else if(ctx->splt_list[i].sample_depth == 8)
   390              {
   391                  if( (chunk.length - keyword_len - 2) % 6 != 0) return SPNG_ECHUNK_SIZE;
   392                  ctx->splt_list[i].n_entries = (chunk.length - keyword_len - 2) / 6;
   393              }
   394              else return SPNG_ESPLT_DEPTH;
   395
   396              if(ctx->splt_list[i].n_entries == 0) return SPNG_ECHUNK_SIZE;
   397              if(sizeof(struct spng_splt_entry) > SIZE_MAX / ctx->splt_list[i].n_entries) return SPNG_EOVERFLOW;
   398
   399              ctx->splt_list[i].entries = spng__malloc(ctx, sizeof(struct spng_splt_entry) * ctx->splt_list[i].n_entries);
   400              if(ctx->splt_list[i].entries == NULL) return SPNG_EMEM;
   401
   402              const unsigned char *splt = data + keyword_len + 2;
   403
   404              size_t k;
   405              if(ctx->splt_list[i].sample_depth == 16)
   406              {
   407                  for(k=0; k < ctx->splt_list[i].n_entries; k++)
   408                  {
   409                      ctx->splt_list[i].entries[k].red = read_u16(splt + k * 10);
   410                      ctx->splt_list[i].entries[k].green = read_u16(splt + k * 10 + 2);
   411                      ctx->splt_list[i].entries[k].blue = read_u16(splt + k * 10 + 4);
   412                      ctx->splt_list[i].entries[k].alpha = read_u16(splt + k * 10 + 6);
   413                      ctx->splt_list[i].entries[k].frequency = read_u16(splt + k * 10 + 8);
   414                  }
   415              }
   416              else if(ctx->splt_list[i].sample_depth == 8)
   417              {
   418                  for(k=0; k < ctx->splt_list[i].n_entries; k++)
   419                  {
   420                      uint8_t red, green, blue, alpha;
   421                      memcpy(&red,   splt + k * 6, 1);
   422                      memcpy(&green, splt + k * 6 + 1, 1);
   423                      memcpy(&blue,  splt + k * 6 + 2, 1);
   424                      memcpy(&alpha, splt + k * 6 + 3, 1);
   425                      ctx->splt_list[i].entries[k].frequency = read_u16(splt + k * 6 + 4);
   426
   427                      ctx->splt_list[i].entries[k].red = red;
   428                      ctx->splt_list[i].entries[k].green = green;
   429                      ctx->splt_list[i].entries[k].blue = blue;
   430                      ctx->splt_list[i].entries[k].alpha = alpha;
   431                  }
   432              }
   433
   434              ctx->stored |= SPNG_CHUNK_SPLT;
   435          }
   436          else if(!memcmp(chunk.type, type_time, 4))
   437          {
   438              if(ctx->file_time) return SPNG_EDUP_TIME;
   439
   440              if(chunk.length != 7) return SPNG_ECHUNK_SIZE;
   441
   442              struct spng_time time;
   443
   444              time.year = read_u16(data);
   445              memcpy(&time.month, data + 2, 1);
   446              memcpy(&time.day, data + 3, 1);
   447              memcpy(&time.hour, data + 4, 1);
   448              memcpy(&time.minute, data + 5, 1);
   449              memcpy(&time.second, data + 6, 1);
   450
   451              if(check_time(&time)) return SPNG_ETIME;
   452
   453              ctx->file_time = 1;
   454
   455              if(!ctx->user_time) memcpy(&ctx->time, &time, sizeof(struct spng_time));
   456
   457              ctx->stored |= SPNG_CHUNK_TIME;
   458          }
   459          else if(!memcmp(chunk.type, type_text, 4) ||
   460                  !memcmp(chunk.type, type_ztxt, 4) ||
   461                  !memcmp(chunk.type, type_itxt, 4))
   462          {
   463              ctx->file_text = 1;
   464
   465              continue; /* XXX: https://gitlab.com/randy408/libspng/issues/31 */
   466          }
   467          else if(!memcmp(chunk.type, type_offs, 4))
   468          {
   469              if(ctx->file_offs) return SPNG_EDUP_OFFS;
   470
   471              if(chunk.length != 9) return SPNG_ECHUNK_SIZE;
   472
   473              ctx->offs.x = read_s32(data);
   474              ctx->offs.y = read_s32(data + 4);
   475              memcpy(&ctx->offs.unit_specifier, data + 8, 1);
   476
   477              if(check_offs(&ctx->offs)) return SPNG_EOFFS;
   478
   479              ctx->file_offs = 1;
   480              ctx->stored |= SPNG_CHUNK_OFFS;
   481          }
   482          else if(!memcmp(chunk.type, type_exif, 4))
   483          {
   484              if(ctx->file_exif) return SPNG_EDUP_EXIF;
   485
   486              ctx->file_exif = 1;
   487
   488              if(!chunk.length) return SPNG_EEXIF;
   489
   490              struct spng_exif exif;
   491
   492              exif.data = spng__malloc(ctx, chunk.length);
   493              if(exif.data == NULL) return SPNG_EMEM;
   494
   495              memcpy(exif.data, data, chunk.length);
   496              exif.length = chunk.length;
   497
   498              if(check_exif(&exif))
   499              {
   500                  spng__free(ctx, exif.data);
   501                  return SPNG_EEXIF;
   502              }
   503
   504              if(!ctx->user_exif) memcpy(&ctx->exif, &exif, sizeof(struct spng_exif));
   505              else spng__free(ctx, exif.data);
   506
   507              ctx->stored |= SPNG_CHUNK_EXIF;
   508          }
   509      }
   510
   511      return ret;
   512  }
