   514  static int read_chunks_after_idat(spng_ctx *ctx)
   515  {
   516      if(ctx == NULL) return 1;
   517
   518      int ret, discard;
   519      int prev_was_idat = 1;
   520      struct spng_chunk chunk;
   521      unsigned char *data;
   522
   523      memcpy(&chunk, &ctx->last_idat, sizeof(struct spng_chunk));
   524
   525      while( !(ret = read_header(ctx, &discard)))
   526      {
   527          memcpy(&chunk, &ctx->current_chunk, sizeof(struct spng_chunk));
   528
   529          if(!chunk_fits_in_cache(ctx, &ctx->chunk_cache_usage))
   530          {
   531              ret = discard_chunk_bytes(ctx, chunk.length);
   532              if(ret) return ret;
   533              continue;
   534          }
   535
   536          data = ctx->data;
   537
   538          ret = read_chunk_bytes(ctx, chunk.length);
   539          if(ret) return ret;
   540
   541           /* Ignore private chunks */
   542          if( (chunk.type[1] & (1 << 5)) != 0) continue;
   543
   544          /* Critical chunk */
   545          if(is_critical_chunk(&chunk))
   546          {
   547              if(!memcmp(chunk.type, type_iend, 4)) return 0;
   548              else if(!memcmp(chunk.type, type_idat, 4) && prev_was_idat) continue; /* ignore extra IDATs */
   549              else return SPNG_ECHUNK_POS; /* critical chunk after last IDAT that isn't IEND */
   550          }
   551
   552          prev_was_idat = 0;
   553
   554          if(!memcmp(chunk.type, type_chrm, 4)) return SPNG_ECHUNK_POS;
   555          else if(!memcmp(chunk.type, type_gama, 4)) return SPNG_ECHUNK_POS;
   556          else if(!memcmp(chunk.type, type_iccp, 4)) return SPNG_ECHUNK_POS;
   557          else if(!memcmp(chunk.type, type_sbit, 4)) return SPNG_ECHUNK_POS;
   558          else if(!memcmp(chunk.type, type_srgb, 4)) return SPNG_ECHUNK_POS;
   559          else if(!memcmp(chunk.type, type_bkgd, 4)) return SPNG_ECHUNK_POS;
   560          else if(!memcmp(chunk.type, type_hist, 4)) return SPNG_ECHUNK_POS;
   561          else if(!memcmp(chunk.type, type_trns, 4)) return SPNG_ECHUNK_POS;
   562          else if(!memcmp(chunk.type, type_phys, 4)) return SPNG_ECHUNK_POS;
   563          else if(!memcmp(chunk.type, type_splt, 4)) return SPNG_ECHUNK_POS;
   564          else if(!memcmp(chunk.type, type_offs, 4)) return SPNG_ECHUNK_POS;
   565          else if(!memcmp(chunk.type, type_time, 4))
   566          {
   567             if(ctx->file_time) return SPNG_EDUP_TIME;
   568
   569             if(chunk.length != 7) return SPNG_ECHUNK_SIZE;
   570
   571              struct spng_time time;
   572
   573              time.year = read_u16(data);
   574              memcpy(&time.month, data + 2, 1);
   575              memcpy(&time.day, data + 3, 1);
   576              memcpy(&time.hour, data + 4, 1);
   577              memcpy(&time.minute, data + 5, 1);
   578              memcpy(&time.second, data + 6, 1);
   579
   580              if(check_time(&time)) return SPNG_ETIME;
   581
   582              ctx->file_time = 1;
   583
   584              if(!ctx->user_time) memcpy(&ctx->time, &time, sizeof(struct spng_time));
   585
   586              ctx->stored |= SPNG_CHUNK_TIME;
   587          }
   588          else if(!memcmp(chunk.type, type_exif, 4))
   589          {
   590              if(ctx->file_exif) return SPNG_EDUP_EXIF;
   591
   592              ctx->file_exif = 1;
   593
   594              if(!chunk.length) return SPNG_EEXIF;
   595
   596              struct spng_exif exif;
   597
   598              exif.data = spng__malloc(ctx, chunk.length);
   599              if(exif.data == NULL) return SPNG_EMEM;
   600
   601              memcpy(exif.data, data, chunk.length);
   602              exif.length = chunk.length;
   603
   604              if(check_exif(&exif))
   605              {
   606                  spng__free(ctx, exif.data);
   607                  return SPNG_EEXIF;
   608              }
   609
   610              if(!ctx->user_exif) memcpy(&ctx->exif, &exif, sizeof(struct spng_exif));
   611              else spng__free(ctx, exif.data);
   612
   613              ctx->stored |= SPNG_CHUNK_EXIF;
   614          }
   615          else if(!memcmp(chunk.type, type_text, 4) ||
   616                  !memcmp(chunk.type, type_ztxt, 4) ||
   617                  !memcmp(chunk.type, type_itxt, 4))
   618          {
   619              ctx->file_text = 1;
   620
   621              continue; /* XXX: https://gitlab.com/randy408/libspng/issues/31 */
   622          }
   623      }
   624
   625      return ret;
   626  }
