   628  static int calculate_subimages(struct spng_subimage sub[7], size_t *widest_scanline, struct spng_ihdr *ihdr, unsigned channels)
   629  {
   630      if(sub == NULL || ihdr == NULL) return 1;
   631
   632      if(ihdr->interlace_method == 1)
   633      {
   634          sub[0].width = (ihdr->width + 7) >> 3;
   635          sub[0].height = (ihdr->height + 7) >> 3;
   636          sub[1].width = (ihdr->width + 3) >> 3;
   637          sub[1].height = (ihdr->height + 7) >> 3;
   638          sub[2].width = (ihdr->width + 3) >> 2;
   639          sub[2].height = (ihdr->height + 3) >> 3;
   640          sub[3].width = (ihdr->width + 1) >> 2;
   641          sub[3].height = (ihdr->height + 3) >> 2;
   642          sub[4].width = (ihdr->width + 1) >> 1;
   643          sub[4].height = (ihdr->height + 1) >> 2;
   644          sub[5].width = ihdr->width >> 1;
   645          sub[5].height = (ihdr->height + 1) >> 1;
   646          sub[6].width = ihdr->width;
   647          sub[6].height = ihdr->height >> 1;
   648      }
   649      else
   650      {
   651          sub[0].width = ihdr->width;
   652          sub[0].height = ihdr->height;
   653      }
   654
   655      size_t scanline_width, widest = 0;
   656
   657      int i;
   658      for(i=0; i < 7; i++)
   659      {/* Calculate scanline width in bits, round up to the nearest byte */
   660          if(sub[i].width == 0 || sub[i].height == 0) continue;
   661
   662          scanline_width = channels * ihdr->bit_depth;
   663
   664          if(scanline_width > SIZE_MAX / ihdr->width) return SPNG_EOVERFLOW;
   665          scanline_width = scanline_width * sub[i].width;
   666
   667          scanline_width += 8; /* Filter byte */
   668
   669          if(scanline_width < 8) return SPNG_EOVERFLOW;
   670
   671          /* Round up */
   672          if(scanline_width % 8 != 0)
   673          {
   674              scanline_width = scanline_width + 8;
   675              if(scanline_width < 8) return SPNG_EOVERFLOW;
   676
   677              scanline_width -= (scanline_width % 8);
   678          }
   679
   680          scanline_width /= 8;
   681
   682          sub[i].scanline_width = scanline_width;
   683
   684          if(widest < scanline_width) widest = scanline_width;
   685      }
   686
   687      *widest_scanline = widest;
   688
   689      return 0;
   690  }
