   692  static int get_ancillary(spng_ctx *ctx)
   693  {
   694      if(ctx == NULL) return 1;
   695      if(ctx->data == NULL) return 1;
   696      if(!ctx->valid_state) return SPNG_EBADSTATE;
   697
   698      int ret;
   699      if(!ctx->first_idat.offset)
   700      {
   701          ret = read_chunks_before_idat(ctx);
   702          if(ret)
   703          {
   704              ctx->valid_state = 0;
   705              return ret;
   706          }
   707      }
   708
   709      return 0;
   710  }
