   741      int ret;
   742      size_t out_size_required, out_width;
   743
   744      ret = spng_decoded_image_size(ctx, fmt, &out_size_required);
   745      if(ret) return ret;
   746      if(out_size < out_size_required) return SPNG_EBUFSIZ;
   747
   748      out_width = out_size_required / ctx->ihdr.height;
   749
   750      uint8_t channels = 1; /* grayscale or indexed_color */
   751
   752      if(ctx->ihdr.color_type == SPNG_COLOR_TYPE_TRUECOLOR) channels = 3;
   753      else if(ctx->ihdr.color_type == SPNG_COLOR_TYPE_GRAYSCALE_ALPHA) channels = 2;
   754      else if(ctx->ihdr.color_type == SPNG_COLOR_TYPE_TRUECOLOR_ALPHA) channels = 4;
   755
   756      uint8_t bytes_per_pixel;
   757
   758      if(ctx->ihdr.bit_depth < 8) bytes_per_pixel = 1;
   759      else bytes_per_pixel = channels * (ctx->ihdr.bit_depth / 8);
   760
   761      z_stream stream;
   762      stream.zalloc = Z_NULL;
   763      stream.zfree = Z_NULL;
   764      stream.opaque = Z_NULL;
   765
   766      if(inflateInit(&stream) != Z_OK) return SPNG_EZLIB;
   767
   768      int apply_trns = 0;
   769      if(flags & SPNG_DECODE_USE_TRNS && ctx->stored & SPNG_CHUNK_TRNS) apply_trns = 1;
   770
   771      int apply_gamma = 0;
   772      if(flags & SPNG_DECODE_USE_GAMA && ctx->stored & SPNG_CHUNK_GAMA) apply_gamma = 1;
   773
   774      int use_sbit = 0;
   775      if(flags & SPNG_DECODE_USE_SBIT && ctx->stored & SPNG_CHUNK_SBIT) use_sbit = 1;
